def spatial_scatter(ax, df, value, title, cmap, vmin=None, vmax=None):
    x = df['x_plot'].values
    y = df['y_plot'].values
    z = df[value].values
    ok = np.isfinite(x) & np.isfinite(y) & np.isfinite(z)
    sc = ax.scatter(x[ok], y[ok], c=z[ok], s=1.05, cmap=cmap, vmin=vmin, vmax=vmax, linewidths=0, rasterized=True)
    pass
    xmin, xmax = (np.nanmin(x[ok]), np.nanmax(x[ok]))
    ymin, ymax = (np.nanmin(y[ok]), np.nanmax(y[ok]))
    cx, cy = ((xmin + xmax) / 2, (ymin + ymax) / 2)
    side = max(xmax - xmin, ymax - ymin) * 1.06
    ax.set_xlim(cx - side / 2, cx + side / 2)
    ax.set_ylim(cy - side / 2, cy + side / 2)
    ax.set_aspect('equal', adjustable='box')
    ax.axis('off')
    return sc
