def importance_panel(ax, task, xlabel, show_ylabels=True):
    y = np.arange(len(features))
    offsets = {'healthy_reference': -0.11, 'nondiseased_kidney': 0.11}
    for sample, label in SAMPLES:
        q = F[(F['sample'] == sample) & (F['task'] == task)].set_index('feature')
        vals = np.array([q.loc[f, 'importance'] if f in q.index else 0.0 for f in features])
        ax.scatter(vals, y + offsets[sample], s=28, label=label)
    ax.axvline(0, ls='--', lw=0.7, alpha=0.5)
    ax.set_yticks(y)
    if show_ylabels:
        ax.set_yticklabels(features)
    else:
        ax.set_yticklabels([])
        ax.tick_params(axis='y', length=0)
    ax.invert_yaxis()
    ax.set_xlabel(xlabel)
    clean(ax)
importance_panel(axF1, 'persistence', 'Held-out AUC loss\nafter permutation', show_ylabels=True)
